-- name|count   (READ-ONLY probes, dev DB pos_saas)
SELECT 'row_counts_orders', count(*) FROM orders;
SELECT 'row_counts_journal_entries', count(*) FROM journal_entries;
SELECT 'row_counts_journal_entry_lines', count(*) FROM journal_entry_lines;
SELECT 'row_counts_general_ledger', count(*) FROM general_ledger;
SELECT 'row_counts_chart_of_accounts', count(*) FROM chart_of_accounts;
SELECT 'row_counts_invoices_customer', count(*) FROM invoices_customer;
SELECT 'row_counts_invoices_supplier', count(*) FROM invoices_supplier;
SELECT 'row_counts_payments_made', count(*) FROM payments_made;
SELECT 'row_counts_payments_received', count(*) FROM payments_received;
SELECT 'row_counts_salaries', count(*) FROM salaries;
SELECT 'row_counts_inventory_movements', count(*) FROM inventory_movements;
SELECT 'row_counts_accounting_event_outbox', count(*) FROM accounting_event_outbox;
SELECT 'row_counts_fiscal_periods', count(*) FROM fiscal_periods;
SELECT 'row_counts_payments_saas', count(*) FROM payments;
SELECT 'journal_status_'||status, count(*) FROM journal_entries GROUP BY status;
SELECT 'journal_type_'||entry_type, count(*) FROM journal_entries GROUP BY entry_type;
SELECT 'journal_ref_'||coalesce(reference_type,'NULL'), count(*) FROM journal_entries GROUP BY reference_type;
SELECT 'p1_unbalanced_entries_lines_vs_lines', count(*) FROM (SELECT journal_entry_id FROM journal_entry_lines GROUP BY 1 HAVING sum(debit_amount)<>sum(credit_amount)) x;
SELECT 'p2_header_totals_vs_lines_mismatch', count(*) FROM journal_entries je JOIN (SELECT journal_entry_id, sum(debit_amount) d, sum(credit_amount) c FROM journal_entry_lines GROUP BY 1) l ON l.journal_entry_id=je.id WHERE je.total_debit<>l.d OR je.total_credit<>l.c;
SELECT 'p3_header_without_lines', count(*) FROM journal_entries je WHERE NOT EXISTS (SELECT 1 FROM journal_entry_lines l WHERE l.journal_entry_id=je.id);
SELECT 'p3b_posted_header_without_lines', count(*) FROM journal_entries je WHERE je.status='posted' AND NOT EXISTS (SELECT 1 FROM journal_entry_lines l WHERE l.journal_entry_id=je.id);
SELECT 'p4_lines_without_entry', count(*) FROM journal_entry_lines l WHERE NOT EXISTS (SELECT 1 FROM journal_entries je WHERE je.id=l.journal_entry_id);
SELECT 'p5_lines_account_missing', count(*) FROM journal_entry_lines l WHERE NOT EXISTS (SELECT 1 FROM chart_of_accounts c WHERE c.id=l.account_id);
SELECT 'p5b_lines_account_code_mismatch', count(*) FROM journal_entry_lines l JOIN chart_of_accounts c ON c.id=l.account_id WHERE c.account_code<>l.account_code;
SELECT 'p6_lines_cross_tenant_account', count(*) FROM journal_entry_lines l JOIN journal_entries je ON je.id=l.journal_entry_id JOIN chart_of_accounts c ON c.id=l.account_id WHERE c.tenant_id<>je.tenant_id OR c.restaurant_id<>je.restaurant_id OR l.tenant_id<>je.tenant_id;
SELECT 'p7_posted_entry_without_gl', count(*) FROM journal_entries je WHERE je.status='posted' AND NOT EXISTS (SELECT 1 FROM general_ledger g WHERE g.journal_entry_id=je.id);
SELECT 'p8_gl_on_draft_entry', count(*) FROM general_ledger g JOIN journal_entries je ON je.id=g.journal_entry_id WHERE je.status='draft';
SELECT 'p9_gl_cross_scope_vs_entry', count(*) FROM general_ledger g JOIN journal_entries je ON je.id=g.journal_entry_id WHERE g.tenant_id<>je.tenant_id OR g.restaurant_id<>je.restaurant_id;
SELECT 'p10_coa_current_balance_vs_gl_net_mismatch', count(*) FROM chart_of_accounts c LEFT JOIN (SELECT account_id, sum(debit_amount) d, sum(credit_amount) cr FROM general_ledger GROUP BY 1) g ON g.account_id=c.id WHERE c.current_balance <> CASE WHEN c.normal_balance='debit' THEN coalesce(g.d,0)-coalesce(g.cr,0) ELSE coalesce(g.cr,0)-coalesce(g.d,0) END;
SELECT 'p11_orders_restaurant_tenant_mismatch', count(*) FROM orders o JOIN restaurants r ON r.id=o.restaurant_id WHERE r.tenant_id<>o.tenant_id;
SELECT 'p11b_order_items_scope_mismatch', count(*) FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.tenant_id<>i.tenant_id OR o.restaurant_id<>i.restaurant_id;
SELECT 'p11c_order_items_product_scope_mismatch', count(*) FROM order_items i JOIN products p ON p.id=i.product_id WHERE p.tenant_id<>i.tenant_id OR p.restaurant_id<>i.restaurant_id;
SELECT 'p12_orders_total_vs_components', count(*) FROM orders WHERE total_amount <> subtotal + coalesce(tax_amount,0) + coalesce(delivery_fee,0) - coalesce(discount_amount,0);
SELECT 'p13_orders_subtotal_vs_items', count(*) FROM orders o JOIN (SELECT order_id, sum(total_price) s FROM order_items GROUP BY 1) i ON i.order_id=o.id WHERE o.subtotal<>i.s;
SELECT 'p14_orders_without_items', count(*) FROM orders o WHERE NOT EXISTS (SELECT 1 FROM order_items i WHERE i.order_id=o.id);
SELECT 'p15_paid_orders', count(*) FROM orders WHERE lower(btrim(payment_status))='paid';
SELECT 'p15b_paid_orders_without_outbox', count(*) FROM orders o WHERE lower(btrim(payment_status))='paid' AND NOT EXISTS (SELECT 1 FROM accounting_event_outbox x WHERE x.order_id=o.id);
SELECT 'p15c_paid_orders_without_journal', count(*) FROM orders o WHERE lower(btrim(payment_status))='paid' AND NOT EXISTS (SELECT 1 FROM journal_entries je WHERE je.tenant_id=o.tenant_id AND je.restaurant_id=o.restaurant_id AND je.reference_id=o.id AND je.reference_type ILIKE '%order%');
SELECT 'p15d_outbox_completed_without_journal', count(*) FROM accounting_event_outbox x WHERE x.status='completed' AND NOT EXISTS (SELECT 1 FROM journal_entries je WHERE je.tenant_id=x.tenant_id AND je.restaurant_id=x.restaurant_id AND je.reference_id=x.order_id AND je.reference_type ILIKE '%order%');
SELECT 'p15e_outbox_status_'||status, count(*) FROM accounting_event_outbox GROUP BY status;
SELECT 'p16_duplicate_journals_per_reference', count(*) FROM (SELECT tenant_id,restaurant_id,reference_type,reference_id FROM journal_entries WHERE reference_id IS NOT NULL AND status<>'void' GROUP BY 1,2,3,4 HAVING count(*)>1) x;
SELECT 'p17_cust_invoice_balance_mismatch', count(*) FROM invoices_customer WHERE balance_due <> total_amount - amount_paid;
SELECT 'p17b_supp_invoice_balance_mismatch', count(*) FROM invoices_supplier WHERE balance_due <> total_amount - amount_paid;
SELECT 'p18_cust_invoice_paid_vs_payments', count(*) FROM invoices_customer i WHERE i.amount_paid <> coalesce((SELECT sum(amount) FROM payments_received p WHERE p.invoice_id=i.id AND p.status='completed'),0);
SELECT 'p18b_supp_invoice_paid_vs_payments', count(*) FROM invoices_supplier i WHERE i.amount_paid <> coalesce((SELECT sum(amount) FROM payments_made p WHERE p.invoice_id=i.id AND p.status='completed'),0);
SELECT 'p19_payments_received_cross_tenant_invoice', count(*) FROM payments_received p JOIN invoices_customer i ON i.id=p.invoice_id WHERE i.tenant_id<>p.tenant_id OR i.restaurant_id<>p.restaurant_id;
SELECT 'p19b_payments_made_cross_tenant_invoice', count(*) FROM payments_made p JOIN invoices_supplier i ON i.id=p.invoice_id WHERE i.tenant_id<>p.tenant_id OR i.restaurant_id<>p.restaurant_id;
SELECT 'p19c_invoice_cust_cross_tenant_customer', count(*) FROM invoices_customer i JOIN customers_accounting c ON c.id=i.customer_id WHERE i.tenant_id<>c.tenant_id OR i.restaurant_id<>c.restaurant_id;
SELECT 'p19d_invoice_supp_cross_tenant_supplier', count(*) FROM invoices_supplier i JOIN suppliers c ON c.id=i.supplier_id WHERE i.tenant_id<>c.tenant_id OR i.restaurant_id<>c.restaurant_id;
SELECT 'p20_invoice_journal_cross_tenant', count(*) FROM invoices_customer i JOIN journal_entries j ON j.id=i.journal_entry_id WHERE i.tenant_id<>j.tenant_id;
SELECT 'p21_completed_payments_made_without_journal', count(*) FROM payments_made WHERE status='completed' AND journal_entry_id IS NULL;
SELECT 'p21b_completed_payments_received_without_journal', count(*) FROM payments_received WHERE status='completed' AND journal_entry_id IS NULL;
SELECT 'p22_cust_invoices_nondraft_without_journal', count(*) FROM invoices_customer WHERE status NOT IN ('draft','void') AND journal_entry_id IS NULL;
SELECT 'p22b_supp_invoices_nondraft_without_journal', count(*) FROM invoices_supplier WHERE status NOT IN ('draft','void') AND journal_entry_id IS NULL;
SELECT 'p23_salaries_paid', count(*) FROM salaries WHERE status='paid';
SELECT 'p23b_salaries_net_vs_gross_minus_ded', count(*) FROM salaries WHERE net_salary <> gross_salary - total_deductions;
SELECT 'p24_salaries_cross_tenant_employee', count(*) FROM salaries s JOIN employees e ON e.id=s.employee_id WHERE e.tenant_id<>s.tenant_id OR e.restaurant_id<>s.restaurant_id;
SELECT 'p25_payroll_journals', count(*) FROM journal_entries WHERE reference_type ILIKE '%salar%' OR reference_type ILIKE '%payroll%';
SELECT 'p26_posted_after_period_close', count(*) FROM journal_entries je JOIN fiscal_periods fp ON fp.tenant_id=je.tenant_id AND fp.restaurant_id=je.restaurant_id AND je.entry_date BETWEEN fp.start_date AND fp.end_date WHERE fp.status<>'open' AND je.posted_at > fp.closed_at;
SELECT 'p27_inventory_movements_cross_scope_product', count(*) FROM inventory_movements m JOIN products p ON p.id=m.product_id WHERE p.tenant_id<>m.tenant_id OR p.restaurant_id<>m.restaurant_id;
SELECT 'p28_products_negative_stock', count(*) FROM products WHERE quantity_in_stock<0;
SELECT 'p29_inventory_movement_total_cost_mismatch', count(*) FROM inventory_movements WHERE abs(total_cost - quantity*unit_cost) > 0.01;
SELECT 'p30_coa_parent_cross_scope', count(*) FROM chart_of_accounts c JOIN chart_of_accounts p ON p.id=c.parent_id WHERE p.tenant_id<>c.tenant_id OR p.restaurant_id<>c.restaurant_id;
SELECT 'p31_coa_normal_balance_vs_type', count(*) FROM chart_of_accounts WHERE (account_type IN ('asset','expense') AND normal_balance<>'debit') OR (account_type IN ('liability','equity','revenue') AND normal_balance<>'credit');
SELECT 'p32_bank_gl_account_cross_scope', count(*) FROM bank_accounts_ledger b JOIN chart_of_accounts c ON c.id=b.gl_account_id WHERE c.tenant_id<>b.tenant_id OR c.restaurant_id<>b.restaurant_id;
SELECT 'p33_restaurants_without_coa', count(*) FROM restaurants r WHERE NOT EXISTS (SELECT 1 FROM chart_of_accounts c WHERE c.restaurant_id=r.id);
SELECT 'p34_order_item_total_vs_qty_price', count(*) FROM order_items WHERE total_price <> quantity*unit_price - coalesce(discount_amount,0);
